const now = new Date();
const currentMonth = now.getMonth();
const currentYear = now.getFullYear();

const monthMapping = [
  { month: 10, name: 'November', column: 'I' },
  { month: 11, name: 'December', column: 'J' },
  { month: 0, name: 'January', column: 'K' },
  { month: 1, name: 'Febraury', column: 'L' },
  { month: 2, name: 'March', column: 'M' },
  { month: 3, name: 'April', column: 'N' },
  { month: 4, name: 'May', column: 'O' },
  { month: 5, name: 'June', column: 'P' },
  { month: 6, name: 'July', column: 'Q' },
  { month: 7, name: 'August', column: 'R' },
  { month: 8, name: 'September', column: 'S' }
];

const currentMonthConfig = monthMapping.find(m => m.month === currentMonth);

if (!currentMonthConfig) {
  console.log('Month not in payment schedule');
  return [{ json: { 
    status: 'skip',
    message: 'Current month not in payment schedule'
  }}];
}

// Compute cycle start (cycles run Nov to Sep)
const cycleStartYear = currentMonth >= 10 ? currentYear : currentYear - 1;
const cycleStartDate = `${cycleStartYear}-11-01`;
const cycleEndDate = `${cycleStartYear + 1}-10-01`;

console.log('=== WORKFLOW INITIALIZED ===');
console.log('Month:', currentMonthConfig.name);
console.log('Column:', currentMonthConfig.column);
console.log('Cycle:', cycleStartDate, 'to', cycleEndDate);

return [{ json: {
  status: 'proceed',
  monthName: currentMonthConfig.name,
  monthColumn: currentMonthConfig.column,
  cycleStartDate: cycleStartDate,
  cycleEndDate: cycleEndDate,
  messageDays: [1, 2, 3, 4, 5]
}}];

