// ==============================================
// GET MONTH CONFIGURATION
// ==============================================

let monthName;
let monthColumn;
let currentDay;

try {

  const splitNode = $items("Split Into Days")[0].json;

  monthName = splitNode.monthName;
  monthColumn = splitNode.monthColumn;
  currentDay = splitNode.dayNumber;

} catch (error) {

  const today = new Date();

  monthName = today.toLocaleString("default", { month: "long" });
  monthColumn = null;
  currentDay = today.getDate();

}

// ==============================================
// HELPER FUNCTIONS
// ==============================================

function cleanPhoneNumber(number) {

  if (!number) return null;

  let cleaned = String(number).replace(/\D/g, '');

  if (cleaned.length < 10) return null;

  if (cleaned.startsWith('0')) {
    cleaned = '91' + cleaned.substring(1);
  }

  if (!cleaned.startsWith('91') && cleaned.length === 10) {
    cleaned = '91' + cleaned;
  }

  return cleaned;

}

function calculateMonthlyPayment(scheme, value) {

  try {

    const schemeNum = parseFloat(scheme);
    const valueNum = parseFloat(value);

    if (isNaN(schemeNum) || isNaN(valueNum) || schemeNum === 0) {
      return 0;
    }

    return Math.round(valueNum / schemeNum);

  } catch (error) {

    return 0;

  }

}

// ==============================================
// MAIN PROCESSING
// ==============================================

const allItems = $input.all();

const customersToMessage = [];
const errors = [];

let processedRows = 0;
let skippedRows = 0;
let totalMessages = 0;

// Debug log
console.log("=== CONFIGURATION ===");
console.log("Month:", monthName);
console.log("Day:", currentDay);
console.log("Records received:", allItems.length);

// ==============================================
// PROCESS EACH ROW
// ==============================================

for (const item of allItems) {

  try {

    const row = item.json;

    const receiptNo = row.receipt_no;
    const scheme = row.scheme;
    const value = row.value;
    const name = row.name;
    const number = row.number;
    const secondaryNumber = row.secondary_number;
    const type = row.type || "12 Months";
    const district = row.district;

    const monthlyPaymentsLookup = $items("Get Current Month Payments").reduce((acc, p) => { acc[p.json.order_id] = p.json; return acc; }, {});
    const currentMonthPayment = monthlyPaymentsLookup[row.id];

    const rowIndex = item.index + 2;

    // Read payment status from monthly_payments for the current month (truth source)
    const actualStatus = currentMonthPayment?.payment_status === "Completed" ? "Completed" : "Empty";

    const trimmedName = name ? String(name).trim() : null;

    if (!trimmedName) {

      skippedRows++;

      errors.push({
        row: rowIndex,
        error: "Missing name"
      });

      continue;

    }

    if (!number) {

      skippedRows++;

      errors.push({
        row: rowIndex,
        error: "Missing phone number"
      });

      continue;

    }

    const cleanedNumber = cleanPhoneNumber(number);

    if (!cleanedNumber) {

      skippedRows++;

      errors.push({
        row: rowIndex,
        error: "Invalid phone number"
      });

      continue;

    }

    const monthlyAmount = calculateMonthlyPayment(scheme, value);

    if (monthlyAmount === 0) {

      skippedRows++;

      errors.push({
        row: rowIndex,
        error: "Invalid scheme/value"
      });

      continue;

    }

    const cleanedSecondaryNumber =
      secondaryNumber && String(secondaryNumber).trim() !== ""
        ? cleanPhoneNumber(secondaryNumber)
        : "";

    const baseCustomerData = {

      Scheme: scheme,
      Value: value,

      Name: trimmedName,

      receiptNo: receiptNo || "N/A",

      type: type,

      district: district ? String(district).trim() : "N/A",

      amount: monthlyAmount,

      monthName: monthName,
      monthColumn: monthColumn,

      currentPaymentStatus: actualStatus,

      rowNumber: rowIndex,

      messageDay: currentDay,

      timestamp: new Date().toISOString()

    };

    // PRIMARY NUMBER

    customersToMessage.push({

      ...baseCustomerData,

      Number: cleanedNumber,

      numberType: "primary"

    });

    totalMessages++;

    // SECONDARY NUMBER

    if (cleanedSecondaryNumber && cleanedSecondaryNumber.length >= 10) {

      customersToMessage.push({

        ...baseCustomerData,

        Number: cleanedSecondaryNumber,

        numberType: "secondary"

      });

      totalMessages++;

    }

    processedRows++;

  } catch (error) {

    skippedRows++;

    errors.push({

      row: item.index + 2,

      error: error.message

    });

  }

}

// ==============================================
// SUMMARY
// ==============================================

console.log("\n=== PROCESSING SUMMARY ===");

console.log(`Day: ${currentDay} | Month: ${monthName}`);

console.log(`Processed: ${processedRows}`);

console.log(`Total Messages: ${totalMessages}`);

console.log(`Errors/Skipped: ${skippedRows}`);

console.log(`To Message: ${customersToMessage.length}`);

// ==============================================
// RETURN OUTPUT
// ==============================================

if (customersToMessage.length === 0) {

  return [{

    json: {

      status: "no_pending",

      monthName: monthName,

      messageDay: currentDay,

      processedRows: processedRows,

      skippedRows: skippedRows,

      errors: errors

    }

  }];

}

return customersToMessage.map(customer => ({ json: customer }));

